43-    # credentials are a different problem and stay in secrets.yaml under KMS.
44-    # Needed at eval time, so a host must be able to read it: locally that is
45:    # git-credential-fj (home.nix), in CI a netrc line from FORGE_TOKEN.
46-    dotfiles-private.url = "git+https://forge.ko.ag/sauyon/dotfiles-private.git";
47-    dotfiles-private.flake = false;
48-    # Zen browser. Not in nixpkgs (checked against this lock), so it comes from
49-    # the community flake, which ships the `zen-beta` package plus a
50-    # home-manager module built on home-manager's own mkFirefoxModule — so
51-    # `programs.zen-browser` takes the same policies/profiles/extensions/
52-    # nativeMessagingHosts options `programs.firefox` did. home-manager follows
53-    # ours so that module generator is the one our lock pins, not a second copy.
54-    zen-browser.url = "github:0xc000022070/zen-browser-flake";
55-    zen-browser.inputs.nixpkgs.follows = "nixpkgs";
56-    zen-browser.inputs.home-manager.follows = "home-manager";
57-  };
